<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
$canPrescribe=has_permission('prescriptions.create');$canDispense=has_permission('pharmacy.dispense');
if(!$canPrescribe&&!has_permission('prescriptions.view')&&!$canDispense){http_response_code(403);exit('Pharmacy access is not assigned to your account.');}
$doctorId=null;if(current_user()['role_key']==='doctor'){$q=$pdo->prepare('SELECT id FROM doctors WHERE user_id=:id');$q->execute(['id'=>current_user()['id']]);$doctorId=$q->fetchColumn();if(!$doctorId){http_response_code(403);exit('Your doctor profile is not configured.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='prescribe'){
  require_permission('prescriptions.create');$patient=filter_var($_POST['patient_id']??'',FILTER_VALIDATE_INT);$visitId=filter_var($_POST['visit_id']??'',FILTER_VALIDATE_INT);$medicine=filter_var($_POST['medicine_id']??'',FILTER_VALIDATE_INT);$quantity=filter_var($_POST['quantity']??'',FILTER_VALIDATE_INT);$dosage=trim((string)($_POST['dosage']??''));$instructions=trim((string)($_POST['instructions']??''));
  if($doctorId){if(!$visitId){set_flash('danger','Choose one of your consultations before prescribing.');redirect('/hospital%20management/pharmacy/index.php');}$q=$pdo->prepare('SELECT patient_id FROM visits WHERE id=:visit AND doctor_id=:doctor');$q->execute(['visit'=>$visitId,'doctor'=>$doctorId]);$patient=$q->fetchColumn();}
  elseif($visitId){$q=$pdo->prepare('SELECT patient_id FROM visits WHERE id=:visit');$q->execute(['visit'=>$visitId]);$visitPatient=$q->fetchColumn();if($visitPatient!==false&&$patient&&(int)$visitPatient!==(int)$patient){$patient=false;}}
  if(!$patient||!$medicine||!$quantity||$quantity<1||$quantity>10000||$dosage===''||strlen($dosage)>120||strlen($instructions)>255){set_flash('danger','Choose a valid consultation, patient, medicine, dosage, and quantity.');redirect('/hospital%20management/pharmacy/index.php');}
  $pdo->beginTransaction();try{$q=$pdo->prepare('INSERT INTO prescriptions(patient_id,doctor_id,visit_id) VALUES(:patient,:doctor,:visit)');$q->execute(['patient'=>$patient,'doctor'=>$doctorId,'visit'=>$visitId?:null]);$prescription=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO prescription_items(prescription_id,medicine_id,dosage,quantity,instructions) VALUES(:prescription,:medicine,:dosage,:quantity,:instructions)');$q->execute(['prescription'=>$prescription,'medicine'=>$medicine,'dosage'=>$dosage,'quantity'=>$quantity,'instructions'=>$instructions?:null]);$item=(string)$pdo->lastInsertId();record_audit('create','prescription',(string)$prescription,'Medicine prescribed');notify_staff('prescription_issued','prescription',(string)$prescription,current_user()['full_name'].' issued a prescription.');$pdo->commit();set_flash('success','Prescription issued to Pharmacy.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger','Prescription could not be saved.');}
 }elseif($action==='dispense'){
  require_permission('pharmacy.dispense');$item=filter_var($_POST['item_id']??'',FILTER_VALIDATE_INT);if(!$item){set_flash('danger','Invalid prescription item.');redirect('/hospital%20management/pharmacy/index.php');}
  $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT pi.id,pi.quantity,pi.medicine_id,m.name,m.quantity AS stock FROM prescription_items pi JOIN medicines m ON m.id=pi.medicine_id LEFT JOIN prescription_dispensations pd ON pd.prescription_item_id=pi.id WHERE pi.id=:id AND pd.id IS NULL FOR UPDATE');$q->execute(['id'=>$item]);$line=$q->fetch();if(!$line)throw new RuntimeException('This prescription item was already dispensed or is unavailable.');if((int)$line['stock']<(int)$line['quantity'])throw new RuntimeException('Insufficient stock for '.$line['name'].'.');$pdo->prepare('UPDATE medicines SET quantity=quantity-:quantity WHERE id=:id AND quantity>=:quantity')->execute(['quantity'=>$line['quantity'],'id'=>$line['medicine_id']]);$pdo->prepare('INSERT INTO prescription_dispensations(prescription_item_id,dispensed_by,quantity) VALUES(:item,:user,:quantity)')->execute(['item'=>$item,'user'=>current_user()['id'],'quantity'=>$line['quantity']]);record_audit('dispense','prescription_item',(string)$item,'Prescription dispensed; medicine stock reduced');notify_staff('medicine_dispensed','prescription_item',(string)$item,current_user()['full_name'].' dispensed medicine from a prescription.');$pdo->commit();set_flash('success','Medicine dispensed and inventory updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Dispensing failed.');}
 }else{http_response_code(400);exit('Unknown pharmacy action.');}redirect('/hospital%20management/pharmacy/index.php');
}
$patients=$canPrescribe&&!$doctorId?$pdo->query('SELECT id,patient_no,first_name,last_name FROM patients ORDER BY last_name,first_name LIMIT 1000')->fetchAll():[];$visits=[];if($canPrescribe&&$doctorId){$q=$pdo->prepare('SELECT v.id,v.visited_at,p.patient_no,p.first_name,p.last_name FROM visits v JOIN patients p ON p.id=v.patient_id WHERE v.doctor_id=:doctor ORDER BY v.visited_at DESC LIMIT 200');$q->execute(['doctor'=>$doctorId]);$visits=$q->fetchAll();}$medicines=($canPrescribe||has_permission('medicines.view'))?$pdo->query('SELECT id,name,sku,quantity FROM medicines ORDER BY name')->fetchAll():[];
$query='SELECT pi.id,pi.dosage,pi.quantity,pi.instructions,m.name,m.unit,m.sku,p.id AS prescription_id,p.created_at,pt.id AS patient_id,pt.patient_no,pt.first_name,pt.last_name,u.full_name AS doctor_name,pd.id AS dispensed_id,pd.dispensed_at,ph.full_name AS pharmacist FROM prescription_items pi JOIN prescriptions p ON p.id=pi.prescription_id JOIN patients pt ON pt.id=p.patient_id JOIN medicines m ON m.id=pi.medicine_id LEFT JOIN doctors d ON d.id=p.doctor_id LEFT JOIN users u ON u.id=d.user_id LEFT JOIN prescription_dispensations pd ON pd.prescription_item_id=pi.id LEFT JOIN users ph ON ph.id=pd.dispensed_by';
if($doctorId){$query.=' WHERE p.doctor_id='.(int)$doctorId;}
$query.=' ORDER BY p.created_at DESC LIMIT 300';$items=$pdo->query($query)->fetchAll();
$pageTitle='Pharmacy';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Pharmacy</h2><p>Issue prescriptions, dispense medicines, and keep stock levels in sync.</p></div></div>
<?php if($canPrescribe):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Prescribe medicine</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="prescribe"><?php if($doctorId): ?><div class="col-md-4"><label class="form-label">Your consultation</label><select class="form-select" name="visit_id" required><option value="">Select your consultation</option><?php foreach($visits as $v): ?><option value="<?= (int)$v['id'] ?>"><?= e(date('M j, Y',strtotime($v['visited_at'])).' - '.$v['patient_no'].' - '.$v['last_name'].', '.$v['first_name']) ?></option><?php endforeach; ?></select></div><?php else: ?><div class="col-md-4"><label class="form-label">Patient</label><select class="form-select" name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['patient_no'].' - '.$p['last_name'].', '.$p['first_name']) ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="col-md-4"><label class="form-label">Medicine</label><select class="form-select" name="medicine_id" required><option value="">Select medicine</option><?php foreach($medicines as $m):?><option value="<?= (int)$m['id']?>"><?=e($m['name'].' · '.$m['sku'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Dosage</label><input class="form-control" name="dosage" maxlength="120" placeholder="e.g. 500 mg, twice daily" required></div><div class="col-md-2"><label class="form-label">Quantity</label><input class="form-control" name="quantity" type="number" min="1" max="10000" required></div><div class="col-md-10"><label class="form-label">Instructions</label><input class="form-control" name="instructions" maxlength="255" placeholder="Optional directions"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Issue prescription</button></div></form></section><?php endif;?>
<section class="content-card"><div class="card-heading"><h3>Prescription queue</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Issued</th><th>Patient</th><th>Medicine</th><th>Directions</th><th>Quantity</th><th>Status</th></tr></thead><tbody><?php if(!$items):?><tr><td class="empty-state" colspan="6">No prescription items yet.</td></tr><?php else:foreach($items as $i):?><tr><td><?=e(date('M j, Y g:i a',strtotime($i['created_at'])))?></td><td><a href="/hospital%20management/patient/show.php?id=<?=(int)$i['patient_id']?>"><?=e($i['last_name'].', '.$i['first_name'])?></a><br><span class="subtle"><?=e($i['patient_no'])?></span></td><td><?=e($i['name'])?></td><td><?=e($i['dosage'])?><?= $i['instructions']?' · '.e($i['instructions']):''?></td><td><?= (int)$i['quantity']?> <?=e($i['unit'])?></td><td><?php if($i['dispensed_id']):?>Dispensed <?=e(date('M j, g:i a',strtotime($i['dispensed_at'])))?> by <?=e($i['pharmacist']??'staff')?><?php elseif($canDispense):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="dispense"><input type="hidden" name="item_id" value="<?=(int)$i['id']?>"><button class="btn btn-sm btn-primary">Dispense</button></form><?php else:?>Awaiting dispensing<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php if(has_permission('medicines.view')):?><section class="content-card"><div class="card-heading"><h3>Medicine stock</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Medicine</th><th>SKU</th><th>Stock</th></tr></thead><tbody><?php foreach($medicines as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['sku'])?></td><td><?= (int)$m['quantity']?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
